package main

import (
	"context"
	"errors"
	"flag"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"golang.org/x/net/http2"
	"golang.org/x/net/http2/h2c"

	"netapp/internal/netapp"
)

func main() {
	addr := flag.String("addr", ":8080", "listen address")
	flag.Parse()

	srv := netapp.New()

	httpServer := &http.Server{
		Addr: *addr,
		// h2c upgrades cleartext HTTP/1.1 connections to HTTP/2, which
		// net/http does not do on its own outside of TLS.
		Handler:           h2c.NewHandler(srv.Handler(), &http2.Server{}),
		ReadHeaderTimeout: 10 * time.Second,
	}

	go func() {
		slog.Info("listening", "addr", *addr)
		if err := httpServer.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			slog.Error("server stopped", "err", err)
			os.Exit(1)
		}
	}()

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	<-ctx.Done()

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := httpServer.Shutdown(shutdownCtx); err != nil {
		slog.Error("shutdown", "err", err)
	}
}

// Package netapp wires together the extended networking primitives used by
// the application: cleartext HTTP/2 and websockets.
package netapp

import (
	"encoding/json"
	"io"
	"log/slog"
	"net/http"

	"golang.org/x/net/websocket"
)

// Server is the application's HTTP handler set.
type Server struct {
	mux *http.ServeMux
}

// New returns a Server with all routes registered.
func New() *Server {
	s := &Server{mux: http.NewServeMux()}
	s.routes()
	return s
}

// Handler exposes the underlying http.Handler so callers can wrap it (for
// example with h2c) or mount it in an existing server.
func (s *Server) Handler() http.Handler { return s.mux }

func (s *Server) routes() {
	s.mux.HandleFunc("GET /healthz", s.handleHealth)
	s.mux.Handle("GET /ws", websocket.Handler(s.handleWebSocket))
}

// handleHealth reports the negotiated protocol version so clients can verify
// whether HTTP/2 was used.
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status":  "ok",
		"proto":   r.Proto,
		"version": r.ProtoMajorVersion(),
	})
}

// handleWebSocket echoes every message back to the client until the peer
// closes the connection.
func (s *Server) handleWebSocket(conn *websocket.Conn) {
	defer conn.Close()
	if _, err := io.Copy(conn, conn); err != nil {
		slog.Debug("websocket closed", "remote", conn.RemoteAddr(), "err", err)
	}
}

package netapp_test

import (
	"crypto/tls"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"golang.org/x/net/http2"
	"golang.org/x/net/websocket"

	"netapp/internal/netapp"
)

func TestHealthOverHTTP1(t *testing.T) {
	srv := httptest.NewServer(netapp.New().Handler())
	defer srv.Close()

	resp, err := http.Get(srv.URL + "/healthz")
	if err != nil {
		t.Fatalf("get: %v", err)
	}
	defer resp.Body.Close()

	if resp.ProtoMajor != 1 {
		t.Fatalf("ProtoMajor = %d, want 1", resp.ProtoMajor)
	}
	assertHealthy(t, resp)
}

func TestHealthOverHTTP2(t *testing.T) {
	srv := httptest.NewUnstartedServer(netapp.New().Handler())
	srv.EnableHTTP2 = true
	srv.StartTLS()
	defer srv.Close()

	client := &http.Client{
		Transport: &http2.Transport{
			TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
		},
	}

	resp, err := client.Get(srv.URL + "/healthz")
	if err != nil {
		t.Fatalf("get: %v", err)
	}
	defer resp.Body.Close()

	if resp.ProtoMajor != 2 {
		t.Fatalf("ProtoMajor = %d, want 2", resp.ProtoMajor)
	}
	assertHealthy(t, resp)
}

func TestWebSocketEcho(t *testing.T) {
	srv := httptest.NewServer(netapp.New().Handler())
	defer srv.Close()

	wsURL := "ws" + strings.TrimPrefix(srv.URL, "http") + "/ws"
	conn, err := websocket.Dial(wsURL, "", "http://localhost/")
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	_ = conn.SetDeadline(time.Now().Add(5 * time.Second))

	const want = "hello over websocket"
	if _, err := io.WriteString(conn, want); err != nil {
		t.Fatalf("write: %v", err)
	}

	buf := make([]byte, len(want))
	if _, err := io.ReadFull(conn, buf); err != nil {
		t.Fatalf("read: %v", err)
	}
	if got := string(buf); got != want {
		t.Fatalf("echo = %q, want %q", got, want)
	}
}

func assertHealthy(t *testing.T, resp *http.Response) {
	t.Helper()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	var body map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if body["status"] != "ok" {
		t.Fatalf("status field = %q, want ok", body["status"])
	}
}

